def parse_config(args):
    cfg = {}
    i = 0
    while i < len(args):
        key = args[i]
        if key == '--name' and i + 1 < len(args):
            cfg['name'] = args[i + 1]
            i += 2
        elif key == '--times' and i + 1 < len(args):
            cfg['times'] = int(args[i + 1])
            i += 2
        else:
            i += 1
    ____  # 返回 cfg

print(parse_config(['--name', 'Python', '--times', '3']))

