def parse_requirements(text):
    result = []
    for ln in text.strip().splitlines():
        ln = ln.strip()
        if not ln or ln.startswith('#'):
            continue
        for sep in ('==', '>='):
            if sep in ln:
                name, ver = ln.split(sep, 1)
                result.append((name.strip(), sep + ver.strip()))
                break
        else:
            result.append((ln, ''))
    ____  # 返回 result

print(parse_requirements('requests==2.32.3\nflask>=3.0\npytest'))
